"use client";

import { useState } from "react";
import { signOutOfAllDevices } from "./actions";

export function SignOutEverywhere() {
  const [state, setState] = useState<"idle" | "working" | "error">("idle");

  async function handleClick() {
    setState("working");
    try {
      await signOutOfAllDevices();
      // The session cookie on this device was just revoked too — a full
      // navigation (not the router) is needed to pick that up.
      window.location.href = "/signin";
    } catch {
      setState("error");
    }
  }

  return (
    <div className="max-w-md space-y-3 p-6">
      <h2 className="text-base font-medium">Sign out of all devices</h2>
      <p className="text-sm opacity-70">
        This ends every active session for your account, including this one. You&apos;ll need
        to sign in again anywhere you&apos;re currently signed in.
      </p>
      <button
        type="button"
        onClick={handleClick}
        disabled={state === "working"}
        className="flex h-10 items-center justify-center rounded-full bg-foreground px-5 text-sm font-medium text-background transition-colors hover:bg-[#383838] disabled:opacity-60 dark:hover:bg-[#ccc]"
      >
        {state === "working" ? "Signing out everywhere…" : "Sign out of all devices"}
      </button>
      {state === "error" && (
        <p className="text-sm text-red-600 dark:text-red-400">
          Something went wrong. Try again.
        </p>
      )}
    </div>
  );
}

