content.content:
--- .env.example ---
# Clerk (https://dashboard.clerk.com) — authentication and user management.
NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY=pk_test_placeholder
CLERK_SECRET_KEY=sk_test_placeholder

# Point Clerk at this app's own sign-in/sign-up pages instead of its hosted
# account portal fallback, so auth.protect() redirects here on protected routes.
NEXT_PUBLIC_CLERK_SIGN_IN_URL=/signin
NEXT_PUBLIC_CLERK_SIGN_UP_URL=/signup

# In the Clerk Dashboard for this app, under "User & authentication":
#   - Email, phone, username -> enable "Email verification link" (magic link) and "Password"
#     as sign-in options, alongside the existing Google social connection.
#   - Under "Account portal" / "User profile" settings, enable "Allow users to delete
#     their own account" so the /account page can offer account deletion.
# No other secrets are needed — Google OAuth is configured on Clerk's side, not in this app.
--- proxy.ts ---
import { clerkMiddleware } from "@clerk/nextjs/server";

// clerkMiddleware() just needs to run on every request so `auth()`/`auth.protect()`
// work in Server Components. Actual protection lives on the routes that need it
// (see /dashboard and /account) rather than here — path-based middleware matching
// can drift from how Next.js actually routes requests.
export default clerkMiddleware();

export const config = {
  // Run on everything except Next.js internals and static files, plus always on API routes.
  matcher: ["/((?!_next|.*\\..*).*)", "/(api|trpc)(.*)"],
};
--- dashboard/page.tsx ---
import { auth, clerkClient, currentUser } from "@clerk/nextjs/server";

export default async function DashboardPage() {
  await auth.protect();
  const me = await currentUser();
  const client = await clerkClient();
  const { data: team } = await client.users.getUserList({ limit: 20 });

  return (
    <main className="mx-auto max-w-2xl p-8">
      <h1 className="text-2xl font-semibold">Dashboard</h1>
      <p className="mt-2 text-sm opacity-70">
        Signed in as {me?.fullName ?? me?.username ?? "nobody"} (
        {me?.primaryEmailAddress?.emailAddress ?? "—"})
      </p>

      <h2 className="mt-8 text-lg font-medium">Team</h2>
      <ul className="mt-2 space-y-1">
        {team.map((u) => (
          <li key={u.id} className="text-sm">
            {u.fullName ?? u.username ?? u.id} — {u.primaryEmailAddress?.emailAddress ?? "—"} —
            joined {new Date(u.createdAt).toISOString().slice(0, 10)}
          </li>
        ))}
      </ul>
    </main>
  );
}
--- account/[[...account]]/page.tsx ---
import { UserProfile } from "@clerk/nextjs";
import { auth } from "@clerk/nextjs/server";
import { SignOutEverywhere } from "../sign-out-everywhere";

function DevicesIcon() {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      width="16"
      height="16"
    >
      <rect x="2" y="3" width="20" height="14" rx="2" />
      <line x1="8" y1="21" x2="16" y2="21" />
      <line x1="12" y1="17" x2="12" y2="21" />
    </svg>
  );
}

// Password change and account deletion are both built into Clerk's <UserProfile />
// "Security" tab (account deletion needs to be turned on in the Clerk Dashboard
// under User & Authentication -> "Allow users to delete their own account").
// "Sign out of all devices" isn't a built-in page, so it's added as a custom one.
export default async function AccountPage() {
  await auth.protect();

  return (
    <div className="flex flex-1 items-start justify-center bg-zinc-50 px-4 py-16 dark:bg-black">
      <UserProfile path="/account" routing="path">
        <UserProfile.Page label="Devices" url="devices" labelIcon={<DevicesIcon />}>
          <SignOutEverywhere />
        </UserProfile.Page>
      </UserProfile>
    </div>
  );
}

